      "content": "import { expect, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

function setup() {
  const storage = new InMemoryTaskRepository();
  const calls: string[] = [];
  const published: DomainEvent[] = [];
  const tasks: TaskRepository = {
    async findById(id) {
      calls.push(`find:${id}`);
      return storage.findById(id);
    },
    async save(task) {
      calls.push(`save:${task.id}:${task.status}`);
      await storage.save(task);
    },
  };
  const ctx: UseCaseContext = {
    correlationId: 'correlation-1',
    causationId: 'causation-1',
    async publish(events) {
      calls.push('publish');
      published.push(...events);
    },
  };
  return { storage, calls, published, tasks, ctx, usecase: new CompleteTask(tasks) };
}

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'carrega t1, salva completed e publica TaskCompleted após salvar'), async () => {
  const { storage, calls, published, ctx, usecase } = setup();
  const task = Task.create('t1', 'Minha tarefa');
  task.pullEvents();
  await storage.save(task);

  const result = await usecase.execute({ task_id: 't1' }, ctx);

  expect(result).toEqual({ task_id: 't1', status: 'completed' });
  expect((await storage.findById('t1'))?.status).toBe('completed');
  expect(calls).toEqual(['find:t1', 'save:t1:completed', 'publish']);
  expect(published).toHaveLength(1);
  expect(published[0]).toBeInstanceOf(TaskCompleted);
  expect(published[0]!.payload).toEqual({ taskId: 't1' });
  expect(task.pullEvents()).toEqual([]);
});

test(covers([
  'usecase:complete_task',
  'criterion:0001/persistencia-conclusao',
], 'rejeita id inexistente com TASK_NOT_FOUND sem salvar ou publicar'), async () => {
  const { calls, published, ctx, usecase } = setup();

  const error = await usecase.execute({ task_id: 'missing' }, ctx).catch(error => error);

  expect(error).toBeInstanceOf(DomainError);
  expect(error).toHaveProperty('code', 'TASK_NOT_FOUND');
  expect(calls).toEqual(['find:missing']);
  expect(published).toEqual([]);
});

test(covers(['usecase:complete_task'], 'rejeita conclusão repetida sem salvar ou publicar novamente'), async () => {
  const { storage, calls, published, ctx, usecase } = setup();
  const task = Task.create('t1', 'Minha tarefa');
  task.pullEvents();
  await storage.save(task);
  await usecase.execute({ task_id: 't1' }, ctx);
  calls.length = 0;
  published.length = 0;

  const error = await usecase.execute({ task_id: 't1' }, ctx).catch(error => error);

  expect(error).toBeInstanceOf(DomainError);
  expect(error).toHaveProperty('code', 'TASK_ALREADY_COMPLETED');
  expect(calls).toEqual(['find:t1']);
  expect(published).toEqual([]);
  expect(task.status).toBe('completed');
  expect(task.pullEvents()).toEqual([]);
});

test(covers(['usecase:complete_task'], 'propaga falha de persistência sem publicar eventos'), async () => {
  const { storage, tasks, calls, published, ctx } = setup();
  const task = Task.create('t1', 'Minha tarefa');
  task.pullEvents();
  await storage.save(task);
  const failure = new Error('Falha ao salvar');
  tasks.save = async () => { throw failure; };

  const error = await new CompleteTask(tasks).execute({ task_id: 't1' }, ctx).catch(error => error);

  expect(error).toBe(failure);
  expect(calls).toEqual(['find:t1']);
  expect(published).toEqual([]);
});
